// ============================================================
// TRAVAS DE FOLLOW-UP — v3 (dia combinado)
// Decisão determinística por linha. Para cada follow-up vencido,
// decide UMA de três ações:
//   enviar_lead      → segue para o Juiz e depois para o envio.
//   notificar_samuel → lead de INSTAGRAM com DIA COMBINADO cuja
//                      janela da Meta já fechou: a Carol não pode
//                      mais enviar pela API, então o Samuel recebe
//                      um WhatsApp para retomar manualmente.
//   reagendar        → ainda não é hora certa (regrava horário) OU
//                      encerra o ciclo (status 'encerrado').
//
// DECISÃO DO SAMUEL: máximo de 2 tentativas por lead (etapa 1
// ~1h e etapa 2 ~24h) em QUALQUER canal. Etapa 3+ encerra.
//
// NOVO na v3 — DIA COMBINADO:
//   Quando o cliente combinou um dia para ser contactado (coluna
//   dia_combinado, gravada pelo Omnichannel), a linha vence nesse
//   dia. WhatsApp: segue o fluxo normal (enviar_lead). Instagram:
//   se a janela de 24h da Meta ainda estiver aberta, segue normal;
//   se já fechou, acao = notificar_samuel (aviso manual).
//
// REGRAS POR CANAL:
//   INSTAGRAM: janela da Meta — só pode enviar se passaram
//   MENOS de 23h30 da última msg do lead (30 min de margem
//   sobre as 24h). Se a janela fechou: encerra (ou avisa o
//   Samuel, se houver dia combinado).
//   WHATSAPP: não existe janela da Meta (número normal, Z-API).
//
// AMBOS: janela comercial 7h–20h, seg–sáb, Boston.
// ============================================================
const TZ = 'America/New_York';
const agora = $now.setZone(TZ);

function proximaJanelaValida(dt) {
  let t = dt;
  for (let i = 0; i < 14; i++) {
    if (t.weekday === 7) { t = t.plus({ days: 1 }).set({ hour: 7, minute: 0, second: 0, millisecond: 0 }); continue; }
    if (t.hour < 7)      { t = t.set({ hour: 7, minute: 0, second: 0, millisecond: 0 }); continue; }
    if (t.hour >= 20)    { t = t.plus({ days: 1 }).set({ hour: 7, minute: 0, second: 0, millisecond: 0 }); continue; }
    return t;
  }
  return t;
}

function dentroJanelaComercial(dt) {
  return dt.weekday !== 7 && dt.hour >= 7 && dt.hour < 20;
}

const saida = [];

for (const item of $input.all()) {
  const row = item.json || {};
  if (!row.id || !row.identificador) continue; // item vazio do Always Output Data

  const etapa = Number(row.etapa || 1);
  const canal = String(row.canal || 'instagram');
  const ultimaCliente = DateTime.fromISO(String(row.ultima_msg_cliente_em || ''), { zone: TZ });
  if (!ultimaCliente.isValid) continue;

  // Limite absoluto da janela da Meta (23h30 após a última msg do lead).
  // Só vale para Instagram/Messenger — WhatsApp não tem essa janela.
  const limiteMeta = ultimaCliente.plus({ hours: 23, minutes: 30 });

  const base = {
    ...row,
    etapa,
    canal,
    _agora: agora.toISO(),
    _limite_meta: limiteMeta.toISO()
  };

  // ---------- DIA COMBINADO + INSTAGRAM + janela da Meta fechada ----------
  // O cliente pediu contato neste dia, mas a Carol não pode mais
  // enviar pela API da Meta → o Samuel recebe um WhatsApp para
  // retomar manualmente. (O aviso vai para o Samuel, não para o
  // lead, por isso não depende da janela comercial.)
  const diaCombinado = String(row.dia_combinado || '').trim();
  if (diaCombinado && canal !== 'whatsapp' && agora > limiteMeta) {
    saida.push({ json: { ...base, acao: 'notificar_samuel' } });
    continue;
  }

  // ---------- ETAPA 3+ → encerra ----------
  // Também apanha linhas antigas que ficaram paradas em etapa 3/4.
  if (etapa >= 3 || etapa < 1 || Number.isNaN(etapa)) {
    saida.push({ json: { ...base, acao: 'reagendar', status: 'encerrado',
      proxima_tentativa_em: row.proxima_tentativa_em,
      motivo_trava: 'ciclo completo (max 2 tentativas)' } });
    continue;
  }

  // ============================================================
  // WHATSAPP — etapas 1 e 2; sem janela da Meta.
  // ============================================================
  if (canal === 'whatsapp') {

    // Fora do horário comercial? Adia para a próxima janela.
    if (!dentroJanelaComercial(agora)) {
      saida.push({ json: { ...base, acao: 'reagendar',
        proxima_tentativa_em: proximaJanelaValida(agora).toISO(),
        motivo_trava: 'fora do horario comercial' } });
      continue;
    }

    // Pode enviar ao lead.
    saida.push({ json: { ...base, acao: 'enviar_lead' } });
    continue;
  }

  // ============================================================
  // INSTAGRAM / MESSENGER — etapas 1 e 2; com janela da Meta.
  // ============================================================

  // Janela da Meta já fechou? O lead não pode mais receber pela
  // API — sem dia combinado, o ciclo encerra (o caso COM dia
  // combinado já foi tratado acima, com aviso ao Samuel).
  if (agora > limiteMeta) {
    saida.push({ json: { ...base, acao: 'reagendar', status: 'encerrado',
      proxima_tentativa_em: row.proxima_tentativa_em,
      motivo_trava: 'janela da Meta fechou antes da etapa ' + etapa } });
    continue;
  }

  // Fora do horário comercial agora? Tenta adiar para a próxima
  // janela — mas só se ela ainda couber dentro da janela da Meta.
  if (!dentroJanelaComercial(agora)) {
    const proxima = proximaJanelaValida(agora);
    if (proxima <= limiteMeta) {
      saida.push({ json: { ...base, acao: 'reagendar',
        proxima_tentativa_em: proxima.toISO(),
        motivo_trava: 'fora do horario comercial' } });
    } else {
      saida.push({ json: { ...base, acao: 'reagendar', status: 'encerrado',
        proxima_tentativa_em: row.proxima_tentativa_em,
        motivo_trava: 'sem horario comercial dentro da janela da Meta' } });
    }
    continue;
  }

  // Tudo certo: pode enviar ao lead.
  saida.push({ json: { ...base, acao: 'enviar_lead' } });
}

return saida;

// ============================================================
// MONTAR ANÁLISE DO JUIZ — v6 (intervenção humana na transcrição)
// Junta o lead da vez (do Loop) com o histórico da conversa e
// produz uma transcrição limpa para o Juiz avaliar. Nada de IA
// aqui — só preparação.
//
// LIGAÇÃO (igual à v3): este node recebe a ENTRADA do node
// "Buscar Playbook de Vendas" (linhas da tabela
// playbook_vendas_miranda). O histórico é lido por referência:
// $('FOLLOW-UP | Buscar Histórico Follow-up').all().
//
// NOVO na v6:
//   - Mensagens enviadas manualmente pela equipe (origem =
//     'humano') aparecem na transcrição como "EQUIPE (humano -
//     Samuel)" em vez de "AGENTE". Assim o Juiz enxerga que um
//     humano interveio (ex.: já agendou com o lead) e pode
//     encerrar/adiar o follow-up em vez de atropelar.
//
// Mantido da v5 (correção do caso Thon):
//   - 'avaliacao' ficou MUITO mais restrito: a Carol fala
//     "Consulta de Avaliação" em quase toda conversa, então a
//     palavra "avaliação" sozinha NÃO define mais o tema. Agora
//     só conta expressão específica de PELE (avaliação de pele,
//     limpeza de pele, manchas, acne, melasma...).
//   - BLOQUEIO de injetáveis: se a conversa é de harmonização,
//     preenchimento, botox, mandíbula, queixo, lábios etc.
//     (tratamentos da Bruna), NENHUM áudio sai — não existe áudio
//     gravado para esse tema e o de "avaliação de pele" fica fora
//     de contexto. Vai follow-up de texto normal.
//
// Mantido da v4: tema_detectado varre a transcrição INTEIRA
// (cliente E agente), 'laser' tem prioridade, e o Preparar Envio
// v5 usa o campo como fallback para lead orgânico.
// Mantido da v3: playbook_rows/bloco_playbook_juiz,
// followups_anteriores/bloco_followups_anteriores,
// dia_combinado_info, idioma determinístico.
// ============================================================
const TZ = 'America/New_York';
const lead = $('FOLLOW-UP | Loop Follow-ups - Leads').item.json;

// ---------- PLAYBOOK (entrada deste node) ----------
const playbookRows = $input.all()
  .map(i => i.json || {})
  .filter(r => r.situacao && r.ativo !== false)
  .sort((a, b) => Number(a.prioridade || 5) - Number(b.prioridade || 5));

let blocoPlaybookJuiz = '';
if (playbookRows.length) {
  blocoPlaybookJuiz =
    'PLAYBOOK DE VENDAS — situações conhecidas (escolha a que MELHOR descreve este lead, ou nenhuma):\n' +
    playbookRows.map(r => '- ' + r.situacao + ' | ' + r.nome + ' | gatilhos: ' + r.gatilhos).join('\n');
}

// ---------- HISTÓRICO (por referência) ----------
const mensagens = $('FOLLOW-UP | Buscar Histórico Follow-up').all()
  .map(i => i.json || {})
  .filter(m => m.id && m.criado_em)
  .sort((a, b) => String(a.criado_em).localeCompare(String(b.criado_em)));

// Mantém só as últimas 30 mensagens (conversa longa não ajuda o Juiz).
const recentes = mensagens.slice(-30);

const linhas = [];
for (const m of recentes) {
  // NOVO v6: mensagem enviada manualmente pela equipe (Samuel) é
  // rotulada como EQUIPE — o Juiz e o Redator precisam saber que
  // um humano interveio (ex.: já agendou) para não atropelar.
  const quem = m.direccao === 'recebida'
    ? 'CLIENTE'
    : (String(m.origem || '') === 'humano' ? 'EQUIPE (humano - Samuel)' : 'AGENTE');
  let conteudo = String(m.conteudo || '').trim();

  // Conteúdo de imagem salvo como JSON → vira marcador simples.
  if (conteudo.startsWith('{')) {
    try {
      const obj = JSON.parse(conteudo);
      if (obj && obj.tipo === 'imagem') conteudo = '[imagem enviada]' + (obj.legenda ? ' ' + obj.legenda : '');
    } catch (e) { /* deixa como está */ }
  }

  if (conteudo === '') conteudo = '[mensagem sem texto registrado]';
  linhas.push(quem + ': ' + conteudo);
}

const transcricao = linhas.join('\n') || '[sem historico registrado]';

// ---------- FOLLOW-UPS JÁ ENVIADOS A ESTE LEAD ----------
const followupsAnteriores = mensagens
  .filter(m => m.origem === 'followup_agente' && (m.direccao === 'enviada' || m.direcao === 'enviada'))
  .map(m => String(m.conteudo || '').trim())
  .filter(Boolean);

let blocoFollowups = '';
if (followupsAnteriores.length) {
  blocoFollowups =
    'FOLLOW-UPS JA ENVIADOS A ESTE LEAD (PROIBIDO repetir ou parafrasear qualquer um deles):\n' +
    followupsAnteriores.map((f, i) => (i + 1) + '. ' + f).join('\n');
}

// Quanto tempo faz que o cliente falou pela última vez.
const ultimaCliente = DateTime.fromISO(String(lead.ultima_msg_cliente_em || ''));
const horasSilencio = ultimaCliente.isValid
  ? Math.round($now.diff(ultimaCliente, 'hours').hours * 10) / 10
  : null;

// ---------- DIA COMBINADO ----------
const diaCombinadoISO = String(lead.dia_combinado || '').trim();
let diaCombinadoInfo = 'NAO';
if (diaCombinadoISO) {
  const dc = DateTime.fromISO(diaCombinadoISO, { zone: TZ });
  if (dc.isValid) {
    const chegou = dc.startOf('day') <= $now.setZone(TZ).endOf('day');
    diaCombinadoInfo = 'SIM — o cliente pediu contato em ' + dc.toFormat('dd/LL/yyyy') +
      (chegou ? ' (CHEGOU A HORA: é hoje, ou o dia já passou)' : ' (ainda não chegou)');
  } else {
    diaCombinadoInfo = 'SIM';
  }
}

// ============================================================
// TEMA DO ÁUDIO DO SAMUEL — determinístico, nada de IA. (v5)
// Varre a transcrição inteira (cliente + agente): o lead muitas
// vezes não escreve "laser" — é a Carol que nomeia o tratamento
// na resposta. O que a conversa discute define o tema.
// Normaliza acentos antes de testar, para pegar "depilação" e
// "depilacao", "avaliação" e "avaliacao" etc.
//
// Regras (v5):
//   1. LASER ganha sempre (tema mais específico).
//   2. INJETÁVEIS (harmonização, botox, preenchimento, queixo,
//      mandíbula...) BLOQUEIAM o tema: não há áudio para isso e o
//      áudio de "avaliação de pele" fica fora de contexto → ''.
//   3. 'avaliacao' só com expressão ESPECÍFICA de pele. A palavra
//      "avaliação" sozinha NÃO conta — a Carol oferece "Consulta
//      de Avaliação" em praticamente toda conversa.
// ============================================================
const textoTema = transcricao
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const TEMA_LASER = /\blaser\b|depila|hair removal|laser hair|depilacion/;
const TEMA_INJETAVEIS = /harmonizacao|preenchimento|\bbotox\b|toxina botulinica|bioestimulador|\bfiller(s)?\b|rinomodelacao|mandibula|queixo|\blabios\b|\bmenton\b|\bjawline\b|\bchin\b|\blips\b/;
const TEMA_PELE = /avaliacao de pele|avaliacao da pele|limpeza de pele|limpeza facial|cuidado(s)? com a pele|tratamento de pele|skin assessment|skin evaluation|skin care|facial cleansing|limpieza facial|limpieza de piel|evaluacion de piel|cuidado de la piel|\bmanchas\b|\bmelasma\b|\bacne\b|rejuvenesc|rejuvenec/;

let temaDetectado = '';
if (TEMA_LASER.test(textoTema)) {
  temaDetectado = 'laser';
} else if (!TEMA_INJETAVEIS.test(textoTema) && TEMA_PELE.test(textoTema)) {
  temaDetectado = 'avaliacao';
}

// ============================================================
// IDIOMA DO CLIENTE — determinístico, nada de IA.
// Varre as mensagens do CLIENTE da mais recente para a mais
// antiga até achar sinal claro de idioma. As mensagens do
// AGENTE nunca contam (é justamente o que confundia o Redator).
// ============================================================
function normalizarTextoIdioma(t) {
  return String(t || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function detectarIdioma(texto) {
  const t = ' ' + normalizarTextoIdioma(texto) + ' ';
  if (t.trim().length < 4) return '';
  const marcas = {
    en: ['the','you','your','are','is','what','where','when','how','much','do','does','can','could','would','like','want','need','have','and','for','with','please','thanks','thank','hi','hello','hey','guys','located','open','price','cost','appointment','book','schedule','it','my','me','about','time','today','tomorrow','week','available','yes','this','that','only','english','sorry','understand','nothing','now','help','information','will','plan','visit','soon','clinic'],
    es: ['hola','donde','cuando','cuanto','como','que','quiero','quisiera','necesito','ustedes','usted','gracias','por','favor','precio','cuesta','cita','agendar','estan','esta','tienen','tiene','hacer','puedo','pueden','una','los','las','mi','para','con','hoy','manana','semana','abierto','buenos','buenas','dias','tardes','noches','si','ubicados','y'],
    pt: ['ola','oi','onde','quando','quanto','como','que','quero','queria','gostaria','preciso','voces','vcs','obrigado','obrigada','por','favor','preco','custa','valor','agendar','marcar','avaliacao','ficam','fica','estao','esta','tem','fazer','posso','podem','uma','os','as','meu','minha','para','pra','com','hoje','amanha','semana','aberto','bom','boa','dia','dias','tarde','tardes','noite','noites','sim','nao','e','ou','vim','anuncio','pele','apos','depois','antes','sabado','sabados','domingo','segunda','terca','quarta','quinta','sexta','feira','tambem','ja','entao','pode','consigo','ate','horario','horarios','melhor','manha','so','mais','tudo','voce','combinado']
  };
  const palavras = t.trim().split(' ');
  const pontos = { en: 0, es: 0, pt: 0 };
  for (const p of palavras) {
    for (const lang of ['en', 'es', 'pt']) {
      if (marcas[lang].includes(p)) pontos[lang]++;
    }
  }
  if (/[¿¡ñ]/.test(String(texto || '').toLowerCase())) pontos.es += 2;
  if (/[çãõ]/.test(String(texto || '').toLowerCase())) pontos.pt += 2;
  const ordem = ['en', 'es', 'pt'].sort((a, b) => pontos[b] - pontos[a]);
  if (pontos[ordem[0]] >= 2 && pontos[ordem[0]] > pontos[ordem[1]]) return ordem[0];
  return '';
}
// conteúdo gerado pela IA (descrição de imagem, transcrição de PDF, análise de
// vídeo) vem em português e NUNCA pode decidir o idioma — só o texto do cliente
function extrairTextoDoClienteIdioma(texto) {
  let t = String(texto || '');
  if (!/<Contexto|Contexto Extra:/i.test(t)) return t;
  const capturas = [];
  const reCap = /<MensagemUsuario>([\s\S]*?)<\/MensagemUsuario>/gi;
  let m;
  while ((m = reCap.exec(t)) !== null) {
    const cap = m[1].trim();
    if (cap && !/^(undefined|null)$/i.test(cap)) capturas.push(cap);
  }
  t = t
    .replace(/<Contexto(Imagem|PDF|Video|Audio|Documento|Arquivo)>[\s\S]*?<\/Contexto\1>/gi, ' ')
    .replace(/<Contexto(Imagem|PDF|Video|Audio|Documento|Arquivo)>[\s\S]*$/gi, ' ')
    .replace(/<(DetalheImagem|TranscricaoPDF|URLVideo|MensagemUsuario)>[\s\S]*?<\/\1>/gi, ' ')
    .replace(/Contexto Extra:[^\n]*/gi, ' ');
  const restante = t.replace(/[ \t]+/g, ' ').trim();
  return (restante + (capturas.length ? '\n' + capturas.join('\n') : '')).trim();
}
const doCliente = recentes.filter(m => m.direccao === 'recebida');
let idiomaCliente = '';
for (let i = doCliente.length - 1; i >= 0; i--) {
  idiomaCliente = detectarIdioma(extrairTextoDoClienteIdioma(doCliente[i].conteudo));
  if (idiomaCliente) break;
}
if (!idiomaCliente) idiomaCliente = 'pt';
const nomesIdioma = { pt: 'PORTUGUES', en: 'INGLES', es: 'ESPANHOL' };

return [{ json: {
  ...lead,
  transcricao,
  idioma_cliente: idiomaCliente,
  idioma_cliente_nome: nomesIdioma[idiomaCliente],
  total_mensagens: mensagens.length,
  horas_silencio: horasSilencio,
  followups_anteriores: followupsAnteriores,
  bloco_followups_anteriores: blocoFollowups,
  playbook_rows: playbookRows,
  bloco_playbook_juiz: blocoPlaybookJuiz,
  dia_combinado_info: diaCombinadoInfo,
  tema_detectado: temaDetectado
} }];

