// ============================================================
// PREPARAR ENVIO FOLLOW-UP — v5 (tema do áudio pela conversa)
// Junta o texto do Redator com o lead, sanitiza a mensagem e
// calcula a próxima etapa do ciclo.
//
// NOVO na v5:
//   - O tema do áudio do Samuel ganha FALLBACK: se o lead NÃO veio
//     de anúncio (tema_audio vazio — lead orgânico), usa o
//     tema_detectado que o Montar Análise do Juiz v4 encontrou na
//     própria conversa. O tema do anúncio, quando existe, continua
//     mandando. Todas as outras condições do áudio seguem iguais.
//     Requer o Montar Análise do Juiz v4 aplicado.
//
// Mantido da v4:
//   1. ÁUDIO DO SAMUEL nas DUAS etapas (1 e 2) do WhatsApp — e
//      portanto também nos leads de "promessa vaga", que nascem
//      direto na etapa 2. Máximo de UM áudio por lead: se o
//      histórico já tem um '[audio follow-up: ...]', vai texto.
//      Contato de DIA COMBINADO nunca leva áudio (precisa ser
//      contextual: "você pediu pra eu te chamar hoje").
//   2. TRAVA DE TAMANHO: texto acima de 300 caracteres é
//      encurtado de forma determinística, preservando a pergunta
//      final.
//   3. Correção de agendamento da etapa 2: se "última msg do
//      cliente + 23h" já passou (ex.: contato de dia combinado,
//      dias depois), a etapa 2 vai para agora + 23h — antes o
//      floor de 30 min fazia dois follow-ups caírem quase juntos.
//   4. dia_combinado sai como null no retorno — depois do envio,
//      o "Atualizar Após Envio" limpa a coluna (dia cumprido).
// ============================================================
const lead = $('FOLLOW-UP | Validar Decisão do Juiz').first().json;

// --- Texto do Redator, sanitizado ---
let texto = String($json.text || $json.output || '').trim()
  .replace(/^```[a-z]*\s*/i, '').replace(/```\s*$/i, '')
  .replace(/^["'\u201C]+|["'\u201D]+$/g, '')   // aspas envolvendo
  .replace(/\u2014/g, '-')                       // travessão
  .replace(/\s+\n/g, '\n')
  .trim();

// --- Idioma e follow-ups anteriores (do Montar Análise do Juiz) ---
let analise = {};
try { analise = $('FOLLOW-UP | Montar Análise do Juiz').first().json || {}; } catch (e) { analise = {}; }
const idiomaLead = ['pt', 'en', 'es'].includes(String(analise.idioma_cliente)) ? String(analise.idioma_cliente) : 'pt';
const followupsAnteriores = Array.isArray(analise.followups_anteriores) ? analise.followups_anteriores : [];
const primeiroNome = String(lead.nome_contacto || '').trim().split(/\s+/)[0] || '';

const FALLBACKS = {
  pt: 'Oi! Ficou alguma dúvida sobre o tratamento? Estou por aqui.',
  en: 'Hi! Any questions I can help with? I am right here.',
  es: 'Hola! Quedó alguna duda sobre el tratamiento? Estoy por aquí.'
};
if (!texto) {
  texto = FALLBACKS[idiomaLead];
}

// ============================================================
// TRAVA ANTI-REPETIÇÃO — determinística, nada de IA.
// Compara o texto do Redator com os follow-ups já enviados a
// este lead. Se for parecido demais (>= 60% das palavras em
// comum), troca por uma variante segura no idioma do lead que
// ainda não tenha sido usada.
// ============================================================
function normalizarComparacao(v) {
  return String(v || '').toLowerCase().normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function similares(a, b) {
  const na = normalizarComparacao(a);
  const nb = normalizarComparacao(b);
  if (!na || !nb) return false;
  if (na === nb) return true;
  const setA = new Set(na.split(' '));
  const setB = new Set(nb.split(' '));
  let comum = 0;
  for (const p of setA) if (setB.has(p)) comum++;
  const jaccard = comum / (setA.size + setB.size - comum);
  return jaccard >= 0.6;
}
function variantesSeguras(idioma, nome) {
  const n = nome ? ' ' + nome : '';
  if (idioma === 'en') return [
    'No rush at all' + (nome ? ', ' + nome : '') + '. Want me to check some other days and times for you?',
    'Hey' + n + ', quick question. Is there anything holding you back that I can help with?',
    'Whatever works best for you' + (nome ? ', ' + nome : '') + '. Would mornings or afternoons be easier?'
  ];
  if (idioma === 'es') return [
    'Sin apuro' + (nome ? ', ' + nome : '') + '. Quieres que revise otros dias y horarios para ti?',
    'Hola' + n + ', una pregunta rapida. Hay algo que te este frenando en lo que pueda ayudar?',
    'Lo que mejor te quede' + (nome ? ', ' + nome : '') + '. Te resulta mas facil por la manana o por la tarde?'
  ];
  return [
    'Sem pressa nenhuma' + (nome ? ', ' + nome : '') + '. Quer que eu veja outros dias e horários pra você?',
    'Oi' + n + ', uma pergunta rápida. Tem algo te segurando em que eu possa ajudar?',
    'Como ficar melhor pra você' + (nome ? ', ' + nome : '') + '. Prefere de manhã ou de tarde?'
  ];
}

let repetiu = false;
if (followupsAnteriores.length && followupsAnteriores.some(f => similares(texto, f))) {
  repetiu = true;
  for (const variante of variantesSeguras(idiomaLead, primeiroNome)) {
    if (!followupsAnteriores.some(f => similares(variante, f))) {
      texto = variante;
      break;
    }
  }
}

// ============================================================
// TRAVA DE TAMANHO — determinística, nada de IA.
// O Redator tem a regra dos 250 caracteres no prompt, mas prompt
// não é garantia. Acima de 300, encurta preservando a pergunta
// final (é ela que reengaja o lead).
// ============================================================
function encurtar(valor) {
  const LIMITE = 300;
  if (valor.length <= LIMITE) return valor;
  const frases = valor.match(/[^.!?\n]+[.!?]*\s*/g) || [valor];
  let pergunta = '';
  for (let i = frases.length - 1; i >= 0; i--) {
    if (frases[i].includes('?')) { pergunta = frases[i].trim(); break; }
  }
  let corpo = '';
  for (const f of frases) {
    const fTrim = f.trim();
    if (!fTrim || fTrim === pergunta) continue;
    const candidato = (corpo + ' ' + fTrim).trim();
    if (candidato.length + (pergunta ? pergunta.length + 1 : 0) > LIMITE) break;
    corpo = candidato;
  }
  let curto = (corpo + (pergunta ? ' ' + pergunta : '')).trim();
  if (!curto || curto.length > LIMITE) curto = valor.slice(0, LIMITE).trim();
  return curto;
}
const tamanhoOriginal = texto.length;
texto = encurtar(texto);
const travaTamanhoAcionada = texto.length < tamanhoOriginal;

// --- contacto_id (para gravar no histórico) ---
let contactoId = '';
try {
  contactoId = $('FOLLOW-UP | Buscar Histórico Follow-up').first().json.contacto_id || '';
} catch (e) { contactoId = ''; }

// ============================================================
// ÁUDIO DO SAMUEL — determinístico, nada de IA.
// Entra quando TUDO bate: canal whatsapp, etapa 1 OU 2, tema
// definido (pelo anúncio de origem OU, novo na v5, detectado na
// própria conversa pelo Montar Análise v4 — leads orgânicos),
// áudio disponível no idioma do lead, NENHUM áudio já enviado a
// este lead e SEM dia combinado.
// Qualquer coisa fora disso -> texto normal.
// ============================================================
const AUDIOS_FOLLOWUP = {
  laser: {
    pt: 'asset://miranda/followup/default'
    // en: '',  // preencher quando o Samuel gravar
    // es: ''
  },
  avaliacao: {
    pt: 'asset://miranda/followup/default'
    // en: '',
    // es: ''
  }
};
const NOMES_TEMA = { laser: 'depilacao a laser', avaliacao: 'avaliacao de pele' };

let tipoEnvio = 'texto';
let audioUrl = '';
// Tema: anúncio de origem manda; se vazio (lead orgânico), vale o
// detectado na conversa pelo Montar Análise do Juiz v4.
const temaDetectado = ['laser', 'avaliacao'].includes(String(analise.tema_detectado || '').trim())
  ? String(analise.tema_detectado).trim()
  : '';
const temaAudio = String(lead.tema_audio || '').trim() || temaDetectado;
const etapaAtual = Number(lead.etapa);
const temDiaCombinado = String(lead.dia_combinado || '').trim() !== '';
const jaRecebeuAudio = followupsAnteriores.some(f => String(f).includes('[audio follow-up:'));

if (
  String(lead.canal || '') === 'whatsapp' &&
  (etapaAtual === 1 || etapaAtual === 2) &&
  !temDiaCombinado &&
  !jaRecebeuAudio &&
  AUDIOS_FOLLOWUP[temaAudio] &&
  AUDIOS_FOLLOWUP[temaAudio][idiomaLead]
) {
  tipoEnvio = 'audio';
  audioUrl = AUDIOS_FOLLOWUP[temaAudio][idiomaLead];
  // O que fica registado no histórico e usado na chave de eco:
  texto = '[audio follow-up: ' + NOMES_TEMA[temaAudio] + ' (' + idiomaLead + ')]';
}

// --- chave de eco (mesmo formato do Omnichannel) ---
function normalizarTexto(valor) {
  return String(valor || '').toLowerCase().normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
}
function textoParaChave(valor) {
  return normalizarTexto(valor).replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '').slice(0, 180);
}
const ecoChave = textoParaChave(texto) || 'sem_conteudo';

// --- próxima etapa do ciclo ---
// Decisão do Samuel: máximo de 2 tentativas em QUALQUER canal.
// Etapa 1 → agenda a etapa 2 (~23h). Depois da etapa 2 → o ciclo
// ENCERRA.
const TZ = 'America/New_York';
const ultima = DateTime.fromISO(String(lead.ultima_msg_cliente_em || ''), { zone: TZ });
let etapaNova, proxima;
let statusNovo = 'agendado';
let motivoEncerramentoNovo = '';
if (etapaAtual === 1) {
  etapaNova = 2;
  proxima = ultima.isValid ? ultima.plus({ hours: 23 }) : $now.plus({ hours: 23 });
  // Se a referência já passou (ex.: contato de dia combinado, dias
  // depois da última msg), a etapa 2 fica para ~23h a partir de agora.
  if (proxima <= $now) proxima = $now.plus({ hours: 23 });
} else {
  etapaNova = 2;                          // etapa 2 foi a última tentativa
  statusNovo = 'encerrado';
  motivoEncerramentoNovo = 'ciclo completo (2 tentativas)';
  proxima = $now;
}
// (janela comercial/Meta é revalidada pelas Travas quando o horário vencer)

return [{ json: {
  ...lead,
  texto_followup: texto,
  tipo_envio: tipoEnvio,
  audio_url: audioUrl,
  trava_anti_repeticao_acionada: repetiu,
  trava_tamanho_acionada: travaTamanhoAcionada,
  eco_chave: ecoChave,
  contacto_id: contactoId,
  etapa_nova: etapaNova,
  proxima_tentativa_nova: proxima.toISO(),
  status_novo: statusNovo,
  motivo_encerramento_novo: motivoEncerramentoNovo,
  dia_combinado: null
} }];

const row = $input.first().json;
const accountId = row.canal === 'whatsapp' ? $env.LEXIA_MIRANDA_ZAPI_ACCOUNT_ID : $env.LEXIA_MIRANDA_INSTAGRAM_ACCOUNT_ID;
if (!row.identificador || !accountId) throw new Error('followup_scope_unavailable');
return [{ json: { row, account_id: accountId, conversation_ref: String(row.identificador) } }];

const input = $('FOLLOW-UP | Preparar escopo do follow-up').first().json;
const rows = (() => { const items = $('FOLLOW-UP | Resolver conversa do follow-up').all(); if (items.length !== 1) throw new Error('Resolver conversa do follow-up output cardinality invalid'); const value = items[0].json; const raw = value.body ?? value; if (typeof raw !== 'string') return raw; const text = raw.trim(); if (!text) return null; try { return JSON.parse(text); } catch { return text; } })();
if (!Array.isArray(rows) || rows.length !== 1) throw new Error('followup_conversation_not_unique');
const state = rows[0], row = input.row;
const requestId = (() => {
  const seedText = String(String(row.id) + ':' + String(row.etapa) + ':' + String(row.proxima_tentativa_em));
  let h1 = 0x811c9dc5, h2 = 0x9e3779b9;
  for (let i = 0; i < seedText.length; i++) {
    h1 = Math.imul(h1 ^ seedText.charCodeAt(i), 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ (seedText.charCodeAt(i) + i), 0x85ebca6b) >>> 0;
  }
  const hex = [h1, h2, h1 ^ h2, Math.imul(h1, 31) ^ h2]
    .map((n) => (n >>> 0).toString(16).padStart(8, '0')).join('');
  return hex.slice(0,8) + '-' + hex.slice(8,12) + '-4' + hex.slice(13,16) + '-8' + hex.slice(17,20) + '-' + hex.slice(20,32);
})();
const actionId = (() => {
  const seedText = String(requestId + ':action:1');
  let h1 = 0x811c9dc5, h2 = 0x9e3779b9;
  for (let i = 0; i < seedText.length; i++) {
    h1 = Math.imul(h1 ^ seedText.charCodeAt(i), 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ (seedText.charCodeAt(i) + i), 0x85ebca6b) >>> 0;
  }
  const hex = [h1, h2, h1 ^ h2, Math.imul(h1, 31) ^ h2]
    .map((n) => (n >>> 0).toString(16).padStart(8, '0')).join('');
  return hex.slice(0,8) + '-' + hex.slice(8,12) + '-4' + hex.slice(13,16) + '-8' + hex.slice(17,20) + '-' + hex.slice(20,32);
})();
let content;
if (row.followup_media_ref && row.followup_media_type === 'image') content = { type: 'image', media_ref: String(row.followup_media_ref), ...(row.texto_followup ? { caption: String(row.texto_followup) } : {}) };
else if (row.tipo_envio === 'audio') content = { type: 'audio', media_ref: 'asset://miranda/followup/' + String(row.tema_audio || 'default') };
else content = { type: 'text', text: String(row.texto_followup || '').trim() };
if (content.type === 'text' && !content.text) throw new Error('followup_text_required');
const scope = { environment: state.environment, cliente_slug: state.cliente_slug, channel: state.channel, account_ref: state.account_id, conversation_ref: state.conversation_ref };
return [{ json: { request: { schema_version: 'lexia.automation.request.v1', request_id: requestId,
  correlation_id: (() => {
  const seedText = String(requestId + ':correlation');
  let h1 = 0x811c9dc5, h2 = 0x9e3779b9;
  for (let i = 0; i < seedText.length; i++) {
    h1 = Math.imul(h1 ^ seedText.charCodeAt(i), 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ (seedText.charCodeAt(i) + i), 0x85ebca6b) >>> 0;
  }
  const hex = [h1, h2, h1 ^ h2, Math.imul(h1, 31) ^ h2]
    .map((n) => (n >>> 0).toString(16).padStart(8, '0')).join('');
  return hex.slice(0,8) + '-' + hex.slice(8,12) + '-4' + hex.slice(13,16) + '-8' + hex.slice(17,20) + '-' + hex.slice(20,32);
})(), kind: 'followup', conversation_id: state.id, scope,
  source_ref: 'followup:' + row.id + ':' + row.etapa, due_at: row.proxima_tentativa_em,
  proposed_actions: [{ schema_version: 'lexia.outbound.action.v1', action_id: actionId, invocation_id: requestId,
    scope, sequence: 1, kind: 'followup', source_ref: 'followup:' + row.id,
    captured_state: { state_version: Number(state.state_version), delivery_epoch: Number(state.delivery_epoch) }, content }] },
  delivery_mode: $env.LEXIA_DELIVERY_MODE || 'observe_only', source_row: row } }];

const row = $input.first().json;
const accountId = row.canal === 'whatsapp' ? $env.LEXIA_MIRANDA_ZAPI_ACCOUNT_ID : $env.LEXIA_MIRANDA_INSTAGRAM_ACCOUNT_ID;
return [{ json: { row, account_id: accountId, conversation_ref: String(row.identificador) } }];

const input = $('FOLLOW-UP | Converter aviso manual em handoff').first().json;
const rows = (() => { const items = $('FOLLOW-UP | Resolver conversa para handoff de follow-up').all(); if (items.length !== 1) throw new Error('Resolver conversa para handoff de follow-up output cardinality invalid'); const value = items[0].json; const raw = value.body ?? value; if (typeof raw !== 'string') return raw; const text = raw.trim(); if (!text) return null; try { return JSON.parse(text); } catch { return text; } })();
if (!Array.isArray(rows) || rows.length !== 1) throw new Error('followup_handoff_conversation_not_unique');
const state = rows[0], ref = (() => {
  const seedText = String(String(input.row.id) + ':followup:handoff');
  let h1 = 0x811c9dc5, h2 = 0x9e3779b9;
  for (let i = 0; i < seedText.length; i++) {
    h1 = Math.imul(h1 ^ seedText.charCodeAt(i), 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ (seedText.charCodeAt(i) + i), 0x85ebca6b) >>> 0;
  }
  const hex = [h1, h2, h1 ^ h2, Math.imul(h1, 31) ^ h2]
    .map((n) => (n >>> 0).toString(16).padStart(8, '0')).join('');
  return hex.slice(0,8) + '-' + hex.slice(8,12) + '-4' + hex.slice(13,16) + '-8' + hex.slice(17,20) + '-' + hex.slice(20,32);
})();
return [{ json: { ...input, state, handoff_ref: ref, rpc_body: { p_conversation_id: state.id,
  p_idempotency_key: 'followup-handoff:' + input.row.id, p_handoff_ref: ref,
  p_motivo: 'followup_requires_manual_contact', p_resumo: String(input.row.motivo_trava || 'Contato manual necessário'),
  p_prioridade: 'normal', p_occurred_at: new Date().toISOString() } } }];

const input = $('FOLLOW-UP | Preparar pendência durável de follow-up').first().json;
const rows = (() => { const items = $('FOLLOW-UP | Criar handoff sem enviar aviso paralelo').all(); if (items.length !== 1) throw new Error('Criar handoff sem enviar aviso paralelo output cardinality invalid'); const value = items[0].json; const raw = value.body ?? value; if (typeof raw !== 'string') return raw; const text = raw.trim(); if (!text) return null; try { return JSON.parse(text); } catch { return text; } })();
const result = Array.isArray(rows) ? rows[0] : rows;
if (!result?.out_handoff_id) throw new Error('central_handoff_id_missing');
const event = { schema_version: 'lexia.crm.event.v1', event_id: (() => {
  const seedText = String(input.handoff_ref + ':crm');
  let h1 = 0x811c9dc5, h2 = 0x9e3779b9;
  for (let i = 0; i < seedText.length; i++) {
    h1 = Math.imul(h1 ^ seedText.charCodeAt(i), 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ (seedText.charCodeAt(i) + i), 0x85ebca6b) >>> 0;
  }
