// ============================================================
// TRAVAS DE LEMBRETE — determinístico, sem IA.
// Recebe as consultas confirmadas das próximas 24h e decide
// quais recebem lembrete AGORA. Monta o texto no idioma do
// cliente (pt/en/es).
//
// Regras:
//   1. Só consultas com status 'confirmado'.
//   2. Lembrete único: se lembrete_enviado_em já existe, pula.
//   3. Janela: faltando 24h ou menos para a consulta.
//   4. Em cima da hora não: faltando menos de 2h, não envia
//      (consulta marcada de última hora não precisa de lembrete).
//   5. Telefone válido (10+ dígitos).
//   6. Só envia entre 7h e 20h (Boston) — se cair fora, a
//      próxima rodada do trigger pega.
// ============================================================
const TZ = 'America/New_York';
const agora = $now.setZone(TZ);

// Janela de envio: 7h–20h (qualquer dia — domingo conta, porque
// o lembrete de uma consulta de segunda de manhã sai no domingo).
if (agora.hour < 7 || agora.hour >= 20) return [];

const saida = [];

for (const item of $input.all()) {
  const row = item.json || {};
  if (!row.event_id) continue;                          // item vazio do Always Output Data
  if (String(row.status || '') !== 'confirmado') continue;
  if (row.lembrete_enviado_em) continue;                // lembrete único

  const inicio = DateTime.fromISO(String(row.inicio || ''), { zone: TZ }).setZone(TZ);
  if (!inicio.isValid) continue;

  const faltamHoras = inicio.diff(agora, 'hours').hours;
  if (faltamHoras > 24) continue;                       // ainda é cedo
  if (faltamHoras < 2) continue;                        // em cima da hora

  const telefone = String(row.telefone || '').replace(/[^0-9]/g, '');
  if (telefone.length < 10) continue;

  // --- idioma e pedaços da mensagem ---
  const idioma = ['pt', 'en', 'es'].includes(String(row.idioma)) ? String(row.idioma) : 'en';
  const primeiroNome = String(row.nome_cliente || '').trim().split(/\s+/)[0] || '';
  const servico = String(row.servico || '').trim() || (idioma === 'pt' ? 'sua consulta' : (idioma === 'es' ? 'tu cita' : 'your appointment'));

  const mesmoDia = inicio.hasSame(agora, 'day');
  const hora = idioma === 'en' ? inicio.toFormat('h:mm a') : inicio.toFormat('HH:mm');

  let mensagem;
  if (idioma === 'pt') {
    const dia = mesmoDia ? 'hoje' : 'amanhã';
    mensagem = 'Oi' + (primeiroNome ? ' ' + primeiroNome : '') + '! Aqui é a Carol, da Miranda Skin Experts. ' +
      'Passando para lembrar da sua consulta de ' + servico + ' ' + dia + ' às ' + hora + '. ' +
      'Você pode me responder por aqui confirmando sua presença, por favor? ' +
      'Se tiver qualquer imprevisto, me avisa que a gente remarca.';
  } else if (idioma === 'es') {
    const dia = mesmoDia ? 'hoy' : 'mañana';
    mensagem = 'Hola' + (primeiroNome ? ' ' + primeiroNome : '') + '! Soy Carol, de Miranda Skin Experts. ' +
      'Te escribo para recordarte tu cita de ' + servico + ' ' + dia + ' a las ' + hora + '. ' +
      'Me respondes por aqui confirmando tu asistencia, por favor? ' +
      'Si surge cualquier imprevisto, avisame y lo reagendamos.';
  } else {
    const dia = mesmoDia ? 'today' : 'tomorrow';
    mensagem = 'Hi' + (primeiroNome ? ' ' + primeiroNome : '') + '! It\'s Carol from Miranda Skin Experts. ' +
      'Just a friendly reminder of your ' + servico + ' appointment ' + dia + ' at ' + hora + '. ' +
      'Could you reply here to confirm you\'re coming, please? ' +
      'If anything comes up, just let me know and we can reschedule.';
  }

  saida.push({ json: {
    event_id: String(row.event_id),
    telefone,
    mensagem,
    nome_cliente: String(row.nome_cliente || ''),
    servico,
    inicio: inicio.toISO(),
    idioma
  } });
}

return saida;

